<?php
if(!registration_ready()){echo '<div class="alert warn">Run <a href="upgrade_v5.php">V5 Upgrade</a> to enable Sign Up and registration approvals.</div>';return;}
$requests=$pdo->query("SELECT id,name,username,approval_status,created_at FROM users WHERE approval_status IN ('Pending','Rejected') ORDER BY CASE WHEN approval_status='Pending' THEN 0 ELSE 1 END,created_at,id")->fetchAll();
?><div class="card table-wrap"><div class="card-head"><div><h3>Registration Requests</h3><span class="muted small">Review new accounts and assign a role before granting access.</span></div><?=badge(count(array_filter($requests,fn($r)=>$r['approval_status']==='Pending')).' Pending','warn')?></div><table class="table"><tr><th>Full Name</th><th>Username</th><th>Submitted</th><th>Status</th><th>Review & Role</th></tr><?php if(!$requests):?><tr><td colspan="5" class="empty-state">No registration requests awaiting approval.</td></tr><?php endif;?><?php foreach($requests as $request):?><tr><td><?=e($request['name'])?></td><td><?=e($request['username'])?></td><td><?=e($request['created_at'])?></td><td><?=badge($request['approval_status']==='Pending'?'Pending Approval':'Rejected',$request['approval_status']==='Pending'?'warn':'danger')?></td><td><form method="post" action="actions.php" class="inline-form wrap" data-confirm="Approve this registration and activate the account with the selected role?"><input type="hidden" name="action" value="approve_registration"><input type="hidden" name="user_id" value="<?=(int)$request['id']?>"><input type="hidden" name="return" value="settings"><label>Access Role<select name="role"><?=role_options_html()?></select></label><button class="btn primary sm">Approve</button></form><?php if($request['approval_status']==='Pending'):?><form method="post" action="actions.php" class="inline-form tiny" data-confirm="Reject this registration? The user will not be able to sign in."><input type="hidden" name="action" value="reject_registration"><input type="hidden" name="user_id" value="<?=(int)$request['id']?>"><input type="hidden" name="return" value="settings"><button class="btn danger sm">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table></div>
